148	+function splitStraceArguments(value: string): string[] {
149	+  const args: string[] = [];
150	+  let start = 0;
151	+  let quoted = false;
152	+  let escaped = false;
153	+  let angleDepth = 0;
154	+  for (let index = 0; index < value.length; index++) {
155	+    const character = value[index]!;
156	+    if (escaped) { escaped = false; continue; }
157	+    if (quoted && character === "\\") { escaped = true; continue; }
158	+    if (character === '"') { quoted = !quoted; continue; }
159	+    if (quoted) continue;
160	+    if (character === "<") { angleDepth++; continue; }
161	+    if (character === ">" && angleDepth > 0) { angleDepth--; continue; }
162	+    if (character === "," && angleDepth === 0) {
163	+      args.push(value.slice(start, index).trim());
164	+      start = index + 1;
165	+    }
166	+  }
167	+  args.push(value.slice(start).trim());
168	+  return args;
169	+}
170	+
171	+function quotedStraceArgument(value: string): string | undefined {
172	+  let index = 0;
173	+  while (/\s/.test(value[index] ?? "")) index++;
174	+  if (value[index] !== '"') return undefined;
175	+  index++;
176	+  let result = "";
177	+  while (index < value.length) {
178	+    const character = value[index++]!;
179	+    if (character === '"') return result;
180	+    result += character;
181	+    if (character === "\\" && index < value.length) result += value[index++]!;
182	+  }
183	+  return undefined;
184	+}
185	+
186	+function decodeStraceString(value: string): string {
187	+  const bytes: number[] = [];
188	+  for (let index = 0; index < value.length;) {
189	+    const character = value[index++]!;
190	+    if (character !== "\\") {
191	+      bytes.push(...Buffer.from(character, "utf8"));
192	+      continue;
193	+    }
194	+    const octal = /^[0-7]{3}/.exec(value.slice(index))?.[0];
195	+    if (octal) {
196	+      bytes.push(parseInt(octal, 8));
197	+      index += octal.length;
198	+      continue;
199	+    }
200	+    const hex = /^x([0-9a-fA-F]{2})/.exec(value.slice(index));
201	+    if (hex) {
202	+      bytes.push(parseInt(hex[1]!, 16));
203	+      index += hex[0].length;
204	+      continue;
205	+    }
206	+    const escaped = value[index++];
207	+    const controls: Record<string, number> = { a: 7, b: 8, f: 12, n: 10, r: 13, t: 9, v: 11 };
208	+    if (escaped === undefined) { bytes.push(92); break; }
209	+    if (escaped in controls) bytes.push(controls[escaped]!);
210	+    else bytes.push(...Buffer.from(escaped, "utf8"));
211	+  }
212	+  return Buffer.from(bytes).toString("utf8");
213	+}
