1	/**
2	 * VR-1 slice 3, gate G-3: `nexus verify` attacked as an untrusted repository or caller would attack it. One test per
3	 * attack; each says in its name what was attempted and asserts that the verdict is not raised. A comment on each says
4	 * how it ends:
5	 *   PREVENTED  the attack has no effect on the verdict, and where a program was to run, it did not;
6	 *   LOWERED    the attack is noticed and the verdict is one that says so (never VERIFIED);
7	 *   LIMIT      a documented limit: the test pins exactly what is and is not protected, so a change shows up here.
8	 * Attacks already covered by the first two slices are not repeated (the table is in docs/VERIFY_IN_CI.md):
9	 * test/verify_command.test.ts (a rewritten scripts.test, a verifier only the head defines, `echo ok`, base equal to
10	 * head, the self-restoring test, a submodule, a repository planted in a linked worktree, the recorded environment) and
11	 * test/verify_typecheck_guard.test.ts (the head's policy file, NEXUS_TRUST_WORKSPACE, weakened tests, a type-checker
12	 * that rewrites its tree). The sandbox itself is test/verify_sandbox.test.ts.
13	 *
14	 * Nearly every case calls verifyChange in this process (a throwaway HOME and temp directory per call; no model, no
15	 * network); the two that are about the command line and the printed output spawn the CLI.
16	 */
17	import { test } from "node:test";
18	import assert from "node:assert/strict";
19	import fs from "node:fs";
20	import os from "node:os";
21	import path from "node:path";
22	import { execFileSync, spawnSync } from "node:child_process";
23	import { isSandboxAvailable } from "../src/sandbox.js";
24	import { discoverWorkspaceTestFiles, MAX_TEST_FILES } from "../src/tester.js";
25	import { VERIFY_MAX_TREE_FILES, VERIFY_RECORDED_ENVIRONMENT, VerifyUsageError, renderVerifyText, verifyChange, type VerifyOperatorContext } from "../src/core/verify.js";
26	import type { VerifyJsonResult } from "../src/verify_contract.js";
27	import {
28	  BASE_FILES, GOOD, MATH_BUGGY, MATH_FIXED, PACKAGE, TEST_FILE, TEST_FULL, TEST_HEAD,
29	  commit, consume, consumeResult, git, head, runCli, verifyInProcess, withRepos, writeFiles,
30	} from "./helpers/verify_fixture.js";
31	
32	const OPERATOR: VerifyOperatorContext = { approveDiscoveredVerifier: true, deliverables: ["src/math.js"], sandbox: { engine: "none" } };
33	const OWN_VERIFIER: VerifyOperatorContext = { verifierCommand: "node --test", deliverables: ["src/math.js"], sandbox: { engine: "none" } };
34	/** The bug stays, and the declared deliverable still counts as changed. */
35	const STILL_BUGGY = `${MATH_BUGGY}// touched\n`;
36	/** The failing assertion rewritten to expect the bug: the same number of tests and assertions, so no heuristic flags it. */
37	const TEST_EXPECTS_BUG = TEST_FULL.replace("assert.equal(add(2, 3), 5)", "assert.equal(add(2, 3), -1)");
38	/** `.PHONY`, or `make test` finds the `test` directory up to date and runs nothing. */
